const $=s=>document.querySelector(s);
const MENU='I can help with:\n1 = I Can Manage guides\n2 = My next visit\n3 = Reminders\n4 = Test results\n5 = Talk to my care team';
const MQ=[['1 I Can Manage','1'],['2 My next visit','2'],['3 Reminders','3'],['4 Test results','4'],['5 Care team','5']];
const MENUQ=[['MENU','MENU']];
const GUIDES=[['Introduction to Head and Neck Cancer',0,'Intro to HNC'],['Introduction to Head and Neck Cancer Treatment',0,'Treatment'],['Introduction to Your Cancer Treatment Team',0,'Care team'],['Understanding Your HNC Surgery',1,'Your surgery'],['Preparing for Head and Neck Surgery',0,'Pre-surgery'],['Managing Your Tracheostomy Tube',0,'Trach tube'],['Managing Your Gastrostomy or Nasogastric Tube',1,'G-tube / NG tube'],['Other Postoperative Considerations',0,'After surgery'],['Postoperative Radiation and Chemotherapy',0,'Radiation / chemo'],['Long Term Survivorship Lifestyle',0,'Survivorship']];
const GR=[[6,/TRACH|STOMA|CANNULA|BREATHING TUBE|SUCTION/],[7,/GASTROSTOMY|G[- ]?TUBE|FEEDING TUBE|NG[- ]TUBE|NASOGASTRIC|TUBE FEED|\bPEG\b/],[6,/\bTUBE\b/],[9,/RADIATION|CHEMO/],[5,/PREPAR|BEFORE (MY )?SURGERY|NIGHT BEFORE|\bPACK/],[8,/AFTER (MY )?SURGERY|POST ?-?OP|DRAIN|SWELLING|SHOULDER/],[4,/UNDERSTAND.*SURGERY|MY SURGERY|WHAT HAPPENS.*SURGERY/],[10,/SURVIV|LIFESTYLE|LONG[- ]TERM|SMOK|EXERCISE/],[3,/TREATMENT TEAM|WHO IS ON|WHO WILL/],[2,/TREATMENT|TREATED/],[1,/WHAT IS (HEAD|HNC)|HEAD AND NECK CANCER|HNC|CANCER/]];
function routeGuide(T){const r=GR.find(x=>x[1].test(T));return r?r[0]:0}
const GQ=GUIDES.map((g,i)=>[(i+1)+' '+g[2],String(i+1)]);
let S;
function reset(){S={on:false,ctx:null,msgs:[],q:[],mc:null,signed:false};$('#consent').checked=false;$('#ph').value='';sync();render()}
function say(t,o){S.msgs.push(Object.assign({a:1,t},o||{}))}
function sync(){$('#on').disabled=S.on||!$('#consent').checked;$('#off').classList.toggle('hide',!S.on);$('#on').classList.toggle('hide',S.on);$('#sRem').disabled=$('#sRes').disabled=!S.on;$('#stat').textContent=S.on?'On':'Off';$('#stat').classList.toggle('on',S.on)}
function reminders(){const r=[...document.querySelectorAll('.rem')].filter(c=>c.checked).map(c=>c.value);return r.length?r.join(', '):'none selected'}
function render(){
const th=$('#th');th.innerHTML='';
if(!S.msgs.length)th.innerHTML='<div class="off">The SMS Health Assistant is off.<br>Turn it on in MyChart settings to start.</div>';
else{const t=document.createElement('div');t.className='ts';t.textContent='Text Message\nToday 9:41 AM';th.append(t)}
S.msgs.forEach(m=>{const d=document.createElement('div');d.className='m'+(m.a?'':' me');d.textContent=m.t;
if(m.lk){const b=document.createElement('button');b.className='lk';b.textContent=LK[m.lk];b.onclick=()=>openMC(m.lk);d.append(b)}
th.append(d);
(m.img||[]).forEach(([k,c])=>{const p=document.createElement('div');p.className='pic';const im=document.createElement('img');im.src=IMG[k];im.alt=c+', photo from the UTSW guide';const sp=document.createElement('span');sp.textContent=c;p.append(im,sp);th.append(p)})});
const last=S.msgs[S.msgs.length-1];
if(last&&!last.a){const dl=document.createElement('div');dl.className='dl';dl.textContent='Delivered';th.append(dl)}
th.scrollTop=th.scrollHeight;
const q=$('#qr');q.innerHTML='';
if(S.on)S.q.forEach(([l,v])=>{const b=document.createElement('button');b.textContent=l;b.onclick=()=>go(v);q.append(b)});
q.classList.toggle('hide',!S.on||!S.q.length);
$('#ti').disabled=!S.on;
$('#tp').classList.toggle('hide',!!S.mc);$('#mp').classList.toggle('hide',!S.mc);
if(S.mc)renderMC();
}
const LK={results:'mychart.utsw.example/r/8Kq2',appt:'mychart.utsw.example/v/3Fm9',set:'mychart.utsw.example/s/7Hp1',learn:'mychart.utsw.example/g/2Vn6'};
const MCT={learn:['Learn › I Can Manage','[Guide title, videos, and steps]'],results:['Test results','[Your test results appear here]'],appt:['Visits','[Next visit: date, time, location, directions]'],set:['Settings › Text messaging','[Reminder and text preferences]']};
function openMC(k){S.mc=k;S.signed=false;render()}
function mk(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e}
function renderMC(){
const el=$('#mc');el.innerHTML='';
el.append(mk('div','mlogo','MyChart'));
const t=MCT[S.mc];
if(!S.signed){
el.append(mk('h2','','Sign in'),mk('p','mut2','For your privacy, please sign in to see '+t[0].toLowerCase()+'.'));
const l1=mk('label','','Username'),i1=mk('input','mi');i1.placeholder='Username';
const l2=mk('label','','Password'),i2=mk('input','mi');i2.type='password';i2.placeholder='Password';
const b=mk('button','mb','Sign in');b.onclick=()=>{S.signed=true;renderMC()};
el.append(l1,i1,l2,i2,b)}
else{el.append(mk('h2','',t[0]),mk('p','mut2',t[1]));for(let i=0;i<4;i++){const l=mk('div','ln');l.style.width=(90-i*12)+'%';el.append(l)}}
}
function go(text){
const v=text.trim();if(!v||!S.on)return;
S.msgs.push({a:0,t:v});S.pq=S.q;S.q=[];render();
setTimeout(()=>{respond(v.toUpperCase());render()},400)
}
function menu(){S.ctx=null;say(MENU);S.q=MQ}
function results(){S.ctx=null;say('Your results aren’t sent by text, to protect your privacy. You can view them securely in MyChart:',{lk:'results'});S.q=MENUQ}
function appt(){S.ctx=null;say('You have an upcoming visit on [date] at [time]. Details, directions, and rescheduling are in MyChart:',{lk:'appt'});S.q=MENUQ}
function rem(){S.ctx=null;say('Visit reminders are on: '+reminders()+'. To change them, open MyChart:',{lk:'set'});S.q=MENUQ}
function care(){S.ctx=null;say('Of course. I’m sending your message to your UTSW care team.\n[Reply time: UTSW to confirm]\nIf you have trouble breathing, call 911. [Emergency wording: UTSW to confirm]');S.q=MENUQ;
setTimeout(()=>{if(S.on){say('UTSW care team: Hi [Name], [care team member] here. [Personal reply]');render()}},1200)}
function mods(){S.ctx='mod';say('These are the UTSW “I Can Manage” guides. Reply with a number to open one:\n'+GUIDES.map((g,i)=>(i+1)+' = '+g[0]+(g[1]?' (coming soon)':'')).join('\n'));S.q=GQ}
function trach(){S.ctx='can';say('Thank you for asking. Caring for your trach tube is an important job, and I’ll walk you through it.\nSource: UTSW “I Can Manage” guide 6, Managing Your Tracheostomy Tube\n\nSo I send the right steps: do you have a reusable inner cannula?\n1 = Yes\n2 = No / not sure\n3 = Show me the supplies first',{img:[['can','Reusable inner cannula']]});S.q=[['1 Yes','1'],['2 No / not sure','2'],['3 Supplies first','3']]}
function glob(T){const gi=routeGuide(T);if(gi){S.ctx='mod';respond(String(gi));return 1}
if(/VISIT|APPOINT/.test(T)){appt();return 1}
if(/REMIND/.test(T)){rem();return 1}
if(/CARE|NURSE|DOCTOR/.test(T)){care();return 1}
if(/MANAGE|GUIDE|MODULE/.test(T)){mods();return 1}
return 0}
function respond(T){
if(T==='STOP'){say('You’re unsubscribed from texts. You can turn the assistant back on in MyChart anytime.');S.on=false;S.q=[];sync();return}
if(T==='MENU')return menu();
if(/LAB|RESULT/.test(T))return results();
const c=S.ctx;
if(c){
if(T==='HELP'||T==='CARE'||(c==='fb'&&T==='3'))return care();
if(c==='mod'){const n=parseInt(T,10);if(n>=1&&n<=10){const g=GUIDES[n-1];if(n===6)return trach();if(g[1]){say('“'+g[0]+'” is still being built, so it isn’t ready yet. Pick another guide, or reply MENU.');S.q=GQ;return}S.ctx=null;say('Here’s a short overview of “'+g[0]+'”: [UTSW to provide a 2–3 sentence summary]. The full guide, with videos, is in MyChart:',{lk:'learn'});S.q=[['More guides','1'],['MENU','MENU']];return}if(glob(T))return;say('Sorry, I didn’t catch that. Reply with a number from 1 to 10, ask me a question, or reply MENU.');S.q=GQ;return}
if(c==='can'){
if(T==='1'||T==='3'){S.ctx='rdy';say('We’ll go one step at a time. You’ll need:\n1. Clean washcloth\n2. Distilled or sterile water\n3. Cotton tipped swabs\n4. Cleaning brush\n5. Tap water\n6. Two clean bowls or cups\n\nReply READY when you have everything.',{img:[['sup','Supplies']]});S.q=[['READY','READY'],['HELP','HELP']];return}
if(T==='2'){S.ctx=null;say('That’s okay. [UTSW to confirm: steps if no reusable inner cannula]. I can connect you with your care team.');S.q=[['CARE','CARE'],['MENU','MENU']];return}}
if(c==='rdy'&&T==='READY'){S.ctx='n1';say('Step 1: Wash your hands with soap and water before you start.\nStep 2: Pour distilled or sterile water into two clean bowls or cups.\nStep 3: Unlock the inner cannula and take it out.\n\nTake your time. Reply NEXT when you’re done, or HELP if you’re stuck.',{img:[['s3','Step 3']]});S.q=[['NEXT','NEXT'],['HELP','HELP']];return}
if(c==='n1'&&T==='NEXT'){S.ctx='n2';say('Step 4: Put the inner cannula into the distilled or sterile water. Use a cotton tip swab or cleaning brush to clean it.\nStep 5: Rinse it with fresh tap water. Shake off excess water.\nStep 6: Dip cotton tipped swabs in fresh distilled or sterile water and clean around your tracheostomy. Wipe from inside the stoma outwards toward the skin.\n\nReply NEXT when ready.',{img:[['s4','Step 4'],['s5','Step 5'],['s6','Step 6']]});S.q=[['NEXT','NEXT'],['HELP','HELP']];return}
if(c==='n2'&&T==='NEXT'){S.ctx='fb';say('Step 7: Put the inner cannula back in and lock it.\nStep 8: Wet a clean washcloth with clean warm water and wipe the skin around your stoma.\nStep 9: Dry your skin with a clean towel.\nStep 10: Wash your hands with soap and water.\n\nYou did it. Thank you for taking such good care.\nWas this helpful?\n1 = Yes\n2 = Not quite\n3 = Talk to my care team',{img:[['s7','Step 7'],['s8','Steps 8–10']]});S.q=[['1 Yes','1'],['2 Not quite','2'],['3 Care team','3']];return}
if(c==='fb'){
if(T==='1'){S.ctx=null;say('I’m so glad. Text me anytime. Reply MENU for other topics.');S.q=MENUQ;return}
if(T==='2'){S.ctx=null;say('Thanks for telling me. I’ll flag this so the UTSW team can improve it. Reply CARE to message your care team.');S.q=[['CARE','CARE'],['MENU','MENU']];return}}
if(c==='rem'){
if(T==='C'){S.ctx=null;say('Thanks, you’re confirmed. See you then.');S.q=MENUQ;return}
if(T==='R'){S.ctx=null;say('To reschedule, use MyChart or call [clinic phone]:',{lk:'appt'});S.q=MENUQ;return}}
if(glob(T))return;say('Sorry, I didn’t catch that. Tap one of the replies below, ask me a question, or reply MENU.');S.q=lastQ();return}
{const gi=routeGuide(T);if(gi){S.ctx='mod';return respond(String(gi))}}
if(T==='1'||/MANAGE|GUIDE|MODULE/.test(T))return mods();
if(T==='2'||/VISIT|APPOINT/.test(T))return appt();
if(T==='3'||/REMIND/.test(T))return rem();
if(T==='4')return results();
if(T==='5'||/CARE|NURSE|DOCTOR/.test(T))return care();
say('Sorry, I’m not sure about that yet. Try asking a question like “how do I clean my trach tube?” or reply MENU.');S.q=MENUQ}
function lastQ(){return S.pq&&S.pq.length?S.pq:MENUQ}
$('#consent').onchange=sync;
$('#on').onclick=()=>{S.on=true;S.msgs=[];S.ctx=null;say('Hi [Name], this is the UTSW Head & Neck Health Assistant. Text me a question anytime. Reply MENU to see what I can help with. Reply STOP to turn off texts.');S.q=MENUQ;sync();render()};
$('#off').onclick=()=>{S.on=false;S.q=[];sync();render()};
$('#sRem').onclick=()=>{S.ctx='rem';say('Reminder from UTSW Head & Neck: you have a visit on [date] at [time]. Reply C to confirm or R to reschedule. Details:',{lk:'appt'});S.q=[['C','C'],['R','R']];render()};
$('#sRes').onclick=()=>{S.ctx=null;say('UTSW: you have a new result in MyChart. For your privacy, results aren’t sent by text. View it securely:',{lk:'results'});S.q=MENUQ;render()};
$('#rst').onclick=reset;
$('#f').onsubmit=e=>{e.preventDefault();const i=$('#ti');go(i.value);i.value=''};
// Photos from the UTSW tracheostomy guide, embedded as data URIs so this file works on its own
const IMG={"can": "data:image/jpeg;base64,", "sup": "data:image/jpeg;base64,", "s3": "data:image/jpeg;base64,", "s4": "data:image/jpeg;base64,", "s5": "data:image/jpeg;base64,", "s6": "data:image/jpeg;base64,", "s7": "data:image/jpeg;base64,", "s8": "data:image/jpeg;base64,"};
$('#bk').onclick=()=>{S.mc=null;render()};
reset();